head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCellInputType]<br/>inputType='custom' 인 Column 의 특정 Body Cell 에 inputType 속성을 설정합니다.",
    "validation" : [
        "info.options(선택) 파라미터로 info.inputType 파라미터값과 연관된 Column 속성값을 객체로 설정할 수 있어야 합니다.",
        "info.options(선택) 파라미터는 추가 설정하려는 Column 속성을 키로 설정합니다.",
        "info.options(선택) 파라미터를 생략 시 기본값(undefined)으로 동작해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] col1~col3 은 inputType=custom + setCellInputTypeCustom=true (typeGetter 미설정) -> setCellInputType 동작 대상. (컬럼 id 는 DataList 컬럼과 일치해야 편집 가능) rowIndex/columnInfo 는 0,0 / info.inputType 은 text 고정.\n[절차] info.options 설정 유무를 선택 후 setCellInputType 실행. 설정 시 Column 속성 textAlign 을 키로 right 값을 전달.\n[확인] 리턴창에 실행 후 Cell 의 textAlign 옵션값(getCellOption) 을 출력. 설정 시 right, 생략 시 undefined(기본값). 해당 Cell(0,0) 을 더블클릭(편집)하면 설정 시 입력값이 우측정렬로 표시됨."', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // 본문 DataList (custom 셀 편집용, 초기값으로 정렬이 보이도록 텍스트 채움)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "정렬확인", "col2": "가운데정렬", "col3": "가운데정렬" },
        { "col1": "", "col2": "", "col3": "" },
        { "col1": "", "col2": "", "col3": "" },
        { "col1": "", "col2": "", "col3": "" }
    ]);

    // target 생성
    //  - setCellInputTypeCustom="true" : custom 컬럼의 Cell 단위 inputType 변경 허용
    //  - 각 Body 컬럼은 inputType="custom" + typeGetter 미설정 (전제)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" setCellInputTypeCustom="true" dataList="data:dlt_bind" ev:oncelldblclick="scwin.target1_oncelldblclick" id="" style="width:560px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="180" inputType="text" id="hcol1" value="col1 (custom)"></w2:column>';
    strTarget += '<w2:column width="180" inputType="text" id="hcol2" value="col2 (custom)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol3" value="col3 (custom)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="180" inputType="custom" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="180" inputType="custom" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="*" inputType="custom" id="col3" dataList="col3"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 해당 Cell 에 적용된 Column 속성(options 키)값을 조회한다.
//  custom 컬럼의 Cell 단위 cellManager.options[key] 를 getCellOption 으로 읽어
//  info.options 로 전달한 Column 속성값이 실제 Cell 에 반영되었는지 확인한다.
//  - 설정 시 : 전달한 값 (예: textAlign=right)
//  - 생략 시 : undefined (기본값)
scwin.getCellOptionValue = function (rowIndex, columnInfo, key) {
    let api = scwin.target1;
    let realRow = api.dataList.getRealRowIndex(rowIndex);
    let val = api.getCellOption(realRow, columnInfo, key);
    return (val === undefined) ? "undefined" : String(val);
};



scwin.btn_setCellInputType_onclick = function () {
    // rowIndex / columnInfo 는 0, 0 고정 / info.inputType 은 text 고정 (이 샘플은 info.options 검증 전용)
    let rowIndex = 0;
    let columnInfo = 0;
    let inputType = "text";

    // info.options 설정 유무 (par_options : "set" 이면 textAlign=right 설정, "" 이면 생략)
    let useOptions = (par_options.getValue() === "set");

    // info 객체 구성
    //  - info.inputType : 필수 (text 고정)
    //  - info.options   : 선택. 설정 시 inputType(text) 과 연관된 Column 속성 textAlign 을 키로 right 전달.
    let info = { inputType: inputType };
    if (useOptions) {
        info.options = { textAlign: "right" };
    }

    // 메소드 실행
    scwin.target1.setCellInputType(rowIndex, columnInfo, info);

    // 셀 단위 재렌더 (적용 결과 표시)
    try { scwin.target1.refreshCell(rowIndex, columnInfo); } catch (e) {}

    wf_body_bottom.getObj("scwin").setReturnValue("셀(0,0) 을 더블클릭하면 편집 input 의 실제 정렬(text-align)을 리턴창에 출력합니다.");
}



// 셀 더블클릭 시(실제 편집모드 진입) 렌더된 편집 input 의 실제 text-align 을 읽어 출력한다.
//  ※ textAlign 은 표시 셀이 아닌 '편집 input' 에 적용되므로, 실제 더블클릭 편집 input 으로 검증한다.
//    (편집 input 은 절대위치라 td 자식이 아니라 document 에 생성됨 -> id 로 조회)
scwin.target1_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    // 더블클릭으로 편집모드 진입 후 렌더된 편집 input(현재 활성 1개) 의 실제 text-align 을 읽는다.
    setTimeout(function () {
        let input = document.querySelector('input[id*="_dynamic_text_"]');
        let align = input ? (input.style.textAlign || getComputedStyle(input).textAlign) : "(편집 input 미생성)";
        wf_body_bottom.getObj("scwin").setReturnValue("text-align : " + align);
    }, 150);
}
